    *pnGroups = *pnMuxes = 0;
    if pObj.iTop == 0 {
        return; }
    pObj1 = Str_NtkObj( p, pObj.iTop ); 
    pObj2 = Str_NtkObj( p, pObj1.iTop );
    *pnMuxes  = pObj1 - pObj + 1;
    *pnGroups = (pObj2 - pObj + 1) / *pnMuxes;
}

