        vSuper.nSize--;
        vCosts.nSize--;
        continue;
    }
    pObj.iCopy = Str_NtkBalanceTwo( pNew, p, pObj, 0, 1, vDelay, pCost, pSuper, pMatrix, 2, nLutSize, -1 );

