    ((p.vFanins.pArray) ? (free((char *) (p.vFanins.pArray)), (p.vFanins.pArray) = 0) : 0);
    // inlining of macro ABC_FREE
    ((p.pObjs) ? (free((char *) (p.pObjs)), (p.pObjs) = 0) : 0);
    // inlining of macro ABC_FREE
    ((p) ? (free((char *) (p)), (p) = 0) : 0);
}
