    fmt.Printf("Network contains %d ands, %d xors, %d muxes (%d trees in %d groups).  ", p.nObjCount[STR_AND], p.nObjCount[STR_XOR], p.nObjCount[STR_MUX], p.nTrees, p.nGroups);
    Abc_PrintTime( 1, "Time", clk );
